import{a,o as i,F as d,af as g,G as p,p as m,b as f,e,f as n,c as v,w as b,B as s}from"./entry.41fbdd66.js";import{_ as w}from"./Downloads.8a48af77.js";import{_ as k}from"./DefaultView.027e2aff.js";import"./FileSaver.min.29897430.js";import"./_commonjsHelpers.87174ba5.js";const x=""+globalThis.__publicAssetsURL("images/buellingen.jpg"),z=""+globalThis.__publicAssetsURL("images/Lagerwochenende-225.jpg"),j=""+globalThis.__publicAssetsURL("images/Irrel2018_12_Party.jpg"),K=""+globalThis.__publicAssetsURL("images/Zeltlager2017_Feuer.jpg");const L={},S={class:"b-container"},A=g('<div class="text-center" data-v-7935a1f0><h3 data-v-7935a1f0>Echte Frönde stonnt tesaame...</h3></div><div class="grid-container" data-v-7935a1f0><p class="grid header" data-v-7935a1f0> .....unter diesem Motto steht die Katholische Pfarrjugend Hüls seit 1978. Spielerisch lernen unsere jungen Mitglieder durch verschiedene Aktivitäten die Bedeutung von Freundschaft, Zusammenhalt und Verantwortung. Neben unseren wöchentlichen Gruppenstunden organisiert die Leiterrunde über das Jahr verteilt verschiedene Aktivitäten. </p><div class="grid pic-1" data-v-7935a1f0><img class="grid-pic" src="'+x+'" data-v-7935a1f0></div><p class="grid text-1" data-v-7935a1f0> Jeden November können sich Kinder ab der vierten Klassen in neu entstehende Mädchen- bzw. Jungengruppen einteilen lassen oder jederzeit in eine gleichaltrige Gruppe eintreten. Die Gruppen treffen sich wöchentlich für 90 Minuten mit ihren Leiter:innen im Heinrich-Joeppen-Haus, um zu spielen, kochen, backen, basteln, toben und viel zu lachen. Dies stärkt ganz besonders den Zusammenhalt, sodass aus der anfangs bunten Truppe meist ein enger Freundeskreis wird. </p><div class="grid pic-2" data-v-7935a1f0><img class="grid-pic" src="'+z+'" data-v-7935a1f0></div><p class="grid text-2" data-v-7935a1f0> Über das Jahr verteilt organisiert die Leiterrunde verschiedene Ausflüge ins Spaßbad oder den Freizeitpark sowie das Kartoffelfeuer mit einer Rallye oder Fahrradtour und Nachtwanderung mit anschließendem Lagerfeuer. Highlight des Jahres ist unser Zeltlager in der vierten und fünften Woche der Sommerferien. Die Favoriten im Programm sind sicher der Singsang am Lagerfeuer, die verschiedenen Stafetten und das Brennball-Turnier, aber auch der gemeinsame Küchen-, Toiletten- oder Ordnungsdienst macht eine Menge Spaß. </p><div class="grid pic-3" data-v-7935a1f0><img class="grid-pic" src="'+j+'" data-v-7935a1f0></div><p class="grid text-3" data-v-7935a1f0> Seit 2021 sind wir als Ortsgruppe „KjG Pfarrjugend Hüls“ der Katholischen jungen Gemeinde (KjG) im Bistum Aachen aktiv. Dies ermöglicht uns spezielle Angebote für unsere Kindergruppen und Leiter:innen wie Gruppenstundenangebote, Erlebniswochenenden oder Fortbildungen anzubieten. </p><div class="grid pic-4" data-v-7935a1f0><img class="grid-pic" src="'+K+'" data-v-7935a1f0></div><p class="footer" data-v-7935a1f0> Hast du Lust bekommen, ein Teil der KPJH zu werden? Dann besuch uns doch mal oder schreibe uns auf <a href="https://www.instagram.com/kpjhuels" data-v-7935a1f0>Instagram</a>, <a href="https://www.facebook.com/kpjh.huels/" data-v-7935a1f0> Facebook</a> oder per <a href="mailto:info@kpjh.de" data-v-7935a1f0>E-Mail</a>! </p></div>',2),G=[A];function U(t,r){return i(),d("div",S,G)}const F=a(L,[["render",U],["__scopeId","data-v-7935a1f0"]]);const H={},c=t=>(m("data-v-58f09818"),t=t(),f(),t),$=c(()=>e("h3",null," Unsere Werte und Normen ",-1)),B=c(()=>e("div",{class:"grid-container"},[e("p",null,[n(" In der KPJH treffen Menschen unterschiedlichen Alters, Herkunft, Glaube, Geschlecht und Orientierung aufeinander. Uns ist es wichtig, dass niemand sich ausgeschlossen fühlt und wir ein freudiges Miteinander schaffen können. Wir nehmen einander ernst und lassen niemanden allein. "),e("br"),n(),e("br"),n(" Bei uns entscheiden alle Mitglieder gemeinsam über die Leitungen und Inhalte des Vereins. Wir setzen uns auch darüber hinaus für eine demokratische, gleichberechtigte und solidarische Gesellschaft ein. Wir treten aktiv gegen Ausgrenzung, Unterdrückung und Umweltzerstörung ein und streben nach gleichen Rechten für alle. "),e("br"),n(),e("br"),n(" Wir engagieren uns kontinuierlich für ein besseres Miteinander und bemühen uns, diese Werte den Kindern zu vermitteln, damit sie zu einem respektvollen Umgang miteinander ermutigt werden. "),e("br"),n(),e("br"),n(" Bei uns ist jeder Willkommen! ")])],-1));function M(t,r){return i(),d(p,null,[$,B],64)}const D=a(H,[["render",M],["__scopeId","data-v-58f09818"]]),I=""+new URL("Satzung-KPJH.068e13f3.pdf",import.meta.url).href,J={data(){return{downloads:[{title:"Satzung - KjG Pfarrjugend Hüls",pdf:{url:I}}]}}},T=e("head",null,[e("title",null,"Über uns")],-1),V=e("div",{class:"text-center"},[e("h3",null,"Downloade hier unsere Satzung")],-1);function N(t,r,P,W,o,R){const u=F,l=D,h=w,_=k;return i(),v(_,{titel:"Das sind wir"},{default:b(()=>[T,s(u),s(l),V,s(h,{downloads:o.downloads},null,8,["downloads"])]),_:1})}const q=a(J,[["render",N]]);export{q as default};
